from sqlalchemy import Column,String,Integer,Float,JSON,Text
from trading_ai.database.base import Base
class _Mixin:
    id=Column(String(128),primary_key=True); symbol=Column(String(32),nullable=False,index=True); scanner_run_id=Column(String(128),nullable=False,index=True); candidate_id=Column(String(128),nullable=True,index=True); snapshot_timestamp=Column(String(64),nullable=False,index=True); payload_json=Column(JSON,nullable=False,default=dict)
def model(name,table,extra=None): return type(name,(_Mixin,Base),{'__tablename__':table,**(extra or {})})
StockScannerRunModel=model('StockScannerRunModel','stock_scanner_runs',{'status':Column(String(32),nullable=False),'provider':Column(String(32),nullable=False,default='polygon')})
StockScannerCandidateModel=model('StockScannerCandidateModel','stock_scanner_candidates',{'category':Column(String(64),nullable=False),'score':Column(Float,nullable=False,default=0)})
StockScannerTimeframeStateModel=model('StockScannerTimeframeStateModel','stock_scanner_timeframe_states',{'timeframe':Column(String(16),nullable=False),'direction':Column(String(32),nullable=False),'structure':Column(String(32),nullable=False)})
StockTradePlanModel=model('StockTradePlanModel','stock_trade_plans',{'state':Column(String(32),nullable=False,default='DRAFT')})
StockScannerPublicationModel=model('StockScannerPublicationModel','stock_scanner_publications',{'publication_name':Column(String(128),nullable=False,index=True),'status':Column(String(32),nullable=False)})
StockSupportResistanceLevelModel=model('StockSupportResistanceLevelModel','stock_support_resistance_levels',{'timeframe':Column(String(32),nullable=False),'primary_timeframe':Column(String(16),nullable=False),'contributing_timeframes':Column(JSON,nullable=False,default=list),'level_type':Column(String(32),nullable=False),'price':Column(Float,nullable=False),'strength':Column(Float,nullable=False)})
StockSupplyDemandZoneModel=model('StockSupplyDemandZoneModel','stock_supply_demand_zones',{'timeframe':Column(String(32),nullable=False),'primary_timeframe':Column(String(16),nullable=False),'contributing_timeframes':Column(JSON,nullable=False,default=list),'zone_type':Column(String(32),nullable=False),'lower_bound':Column(Float,nullable=False),'upper_bound':Column(Float,nullable=False),'strength':Column(Float,nullable=False)})
StockInstitutionalStructureZoneModel=model('StockInstitutionalStructureZoneModel','stock_institutional_structure_zones',{'zone_type':Column(String(32),nullable=False,index=True),'lower_bound':Column(Float,nullable=False),'upper_bound':Column(Float,nullable=False),'representative_price':Column(Float,nullable=False),'strength':Column(Float,nullable=False),'confluence_score':Column(Float,nullable=False),'primary_timeframe':Column(String(16),nullable=False,index=True),'contributing_timeframes':Column(JSON,nullable=False,default=list),'components':Column(JSON,nullable=False,default=list)})
StockAccumulationDistributionSnapshotModel=model('StockAccumulationDistributionSnapshotModel','stock_accumulation_distribution_snapshots',{'state':Column(String(32),nullable=False),'score':Column(Float,nullable=False)})
StockBreakoutSnapshotModel=model('StockBreakoutSnapshotModel','stock_breakout_snapshots',{'state':Column(String(32),nullable=False),'confirmation':Column(Float,nullable=False)})
StockContextSnapshotModel=model('StockContextSnapshotModel','stock_context_snapshots',{'context_score':Column(Float,nullable=False),'context_adjustment':Column(Float,nullable=False)})
StockOpportunityScoreSnapshotModel=model('StockOpportunityScoreSnapshotModel','stock_opportunity_score_snapshots',{'primary_category':Column(String(64),nullable=False),'overall_score':Column(Float,nullable=False),'confidence':Column(Float,nullable=False)})
StockPositionIntelligenceSnapshotModel=model('StockPositionIntelligenceSnapshotModel','stock_position_intelligence_snapshots',{'action':Column(String(32),nullable=False),'thesis_integrity':Column(Float,nullable=False),'management_quality':Column(Float,nullable=False)})
StockOutcomeObservationModel=model('StockOutcomeObservationModel','stock_outcome_observations',{'outcome':Column(String(32),nullable=False,index=True),'setup_category':Column(String(64),nullable=False,index=True),'market_regime':Column(String(64),nullable=False,index=True),'strategy':Column(String(64),nullable=False,index=True),'prediction_probability':Column(Float,nullable=False),'realized_return_pct':Column(Float,nullable=False,default=0),'management_policy':Column(String(64),nullable=False,index=True)})
StockOutcomeAttributionSnapshotModel=model('StockOutcomeAttributionSnapshotModel','stock_outcome_attribution_snapshots',{'attribution_type':Column(String(64),nullable=False,index=True),'attribution_key':Column(String(128),nullable=False,index=True),'observation_count':Column(Integer,nullable=False,default=0)})
StockProbabilityCalibrationSnapshotModel=model('StockProbabilityCalibrationSnapshotModel','stock_probability_calibration_snapshots',{'model_family':Column(String(128),nullable=False,index=True),'model_version':Column(String(128),nullable=False,index=True),'observation_count':Column(Integer,nullable=False,default=0),'brier_score':Column(Float,nullable=True),'expected_calibration_error':Column(Float,nullable=True)})
StockManagementPolicyPerformanceModel=model('StockManagementPolicyPerformanceModel','stock_management_policy_performance',{'policy_name':Column(String(128),nullable=False,index=True),'observation_count':Column(Integer,nullable=False,default=0),'expectancy_pct':Column(Float,nullable=False,default=0),'score':Column(Float,nullable=False,default=0)})
